import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_triu_matmul(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

#define TILE 64
#define TT 4
__global__ void triu_matmul_kernel(const float* __restrict__ A_ptr,
                                    const float* __restrict__ B_ptr,
                                    float* __restrict__ C_ptr,
                                    int N) {
    int tile_row = blockIdx.y;
    int tile_col = blockIdx.x;
    // Blocks entirely below the diagonal contribute nothing to the
    // upper-triangular output; skip them completely.
    if (tile_row > tile_col) return;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    // Each thread computes a TTxTT (4x4) register-blocked sub-tile of C
    int ry0 = ty * TT;
    int cx0 = tx * TT;
    int row_base = tile_row * TILE + ry0;
    int col_base = tile_col * TILE + cx0;
    __shared__ float As_data[TILE * TILE];
    __shared__ float Bs_data[TILE * TILE];
    Tensor As = make_tensor(make_smem_ptr(As_data),
                             make_shape(Int<TILE>{}, Int<TILE>{}),
                             make_stride(Int<TILE>{}, Int<1>{}));
    Tensor Bs = make_tensor(make_smem_ptr(Bs_data),
                             make_shape(Int<TILE>{}, Int<TILE>{}),
                             make_stride(Int<TILE>{}, Int<1>{}));
    Tensor gC = make_tensor(make_gmem_ptr(C_ptr), make_shape(N, N), make_stride(N, Int<1>{}));
    float acc[TT][TT];
    #pragma unroll
    for (int i = 0; i < TT; ++i)
        #pragma unroll
        for (int j = 0; j < TT; ++j)
            acc[i][j] = 0.f;
    // A is upper triangular => A(row, k) == 0 for k < row
    // B is upper triangular => B(k, col) == 0 for k > col
    // So only k-tiles in [tile_row, tile_col] can contribute.
    for (int kt = tile_row; kt <= tile_col; ++kt) {
        int a_col_base = kt * TILE + cx0;
        // Vectorized (float4) loads of contiguous column groups when fully in-bounds
        #pragma unroll
        for (int i = 0; i < TT; ++i) {
            int row = row_base + i;
            if (row < N) {
                if (a_col_base + TT - 1 < N) {
                    float4 av = *reinterpret_cast<const float4*>(A_ptr + row * N + a_col_base);
                    As(ry0 + i, cx0 + 0) = av.x;
                    As(ry0 + i, cx0 + 1) = av.y;
                    As(ry0 + i, cx0 + 2) = av.z;
                    As(ry0 + i, cx0 + 3) = av.w;
                } else {
                    #pragma unroll
                    for (int j = 0; j < TT; ++j) {
                        int col = a_col_base + j;
                        As(ry0 + i, cx0 + j) = (col < N) ? A_ptr[row * N + col] : 0.f;
                    }
                }
            } else {
                #pragma unroll
                for (int j = 0; j < TT; ++j) As(ry0 + i, cx0 + j) = 0.f;
            }
        }
        int b_row_base = kt * TILE + ry0;
        #pragma unroll
        for (int i = 0; i < TT; ++i) {
            int b_row = b_row_base + i;
            if (b_row < N) {
                if (col_base + TT - 1 < N) {
                    float4 bv = *reinterpret_cast<const float4*>(B_ptr + b_row * N + col_base);
                    Bs(ry0 + i, cx0 + 0) = bv.x;
                    Bs(ry0 + i, cx0 + 1) = bv.y;
                    Bs(ry0 + i, cx0 + 2) = bv.z;
                    Bs(ry0 + i, cx0 + 3) = bv.w;
                } else {
                    #pragma unroll
                    for (int j = 0; j < TT; ++j) {
                        int col = col_base + j;
                        Bs(ry0 + i, cx0 + j) = (col < N) ? B_ptr[b_row * N + col] : 0.f;
                    }
                }
            } else {
                #pragma unroll
                for (int j = 0; j < TT; ++j) Bs(ry0 + i, cx0 + j) = 0.f;
            }
        }
        __syncthreads();
        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            float a_reg[TT];
            float b_reg[TT];
            #pragma unroll
            for (int i = 0; i < TT; ++i) a_reg[i] = As(ry0 + i, k);
            #pragma unroll
            for (int j = 0; j < TT; ++j) b_reg[j] = Bs(k, cx0 + j);
            #pragma unroll
            for (int i = 0; i < TT; ++i) {
                #pragma unroll
                for (int j = 0; j < TT; ++j) {
                    acc[i][j] += a_reg[i] * b_reg[j];
                }
            }
        }
        __syncthreads();
    }
    #pragma unroll
    for (int i = 0; i < TT; ++i) {
        int row = row_base + i;
        if (row >= N) continue;
        #pragma unroll
        for (int j = 0; j < TT; ++j) {
            int col = col_base + j;
            if (col < N && row <= col) gC(row, col) = acc[i][j];
        }
    }
}
torch::Tensor cute_triu_matmul(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
    TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
                "Expect float32 tensors");
    int N = (int)A.size(0);
    TORCH_CHECK((int)A.size(1) == N, "A must be square");
    TORCH_CHECK((int)B.size(0) == N && (int)B.size(1) == N, "B must be square and match A");
    auto A_c = A.contiguous();
    auto B_c = B.contiguous();
    // Zero-init since blocks fully below the diagonal, and the
    // lower-triangular part of diagonal blocks, are never written.
    auto C = torch::zeros({N, N}, A.options());
    int num_tiles = (N + TILE - 1) / TILE;
    dim3 block(TILE / TT, TILE / TT);
    dim3 grid(num_tiles, num_tiles);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    triu_matmul_kernel<<<grid, block, 0, stream>>>(
        A_c.data_ptr<float>(), B_c.data_ptr<float>(), C.data_ptr<float>(), N);
    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE triu_matmul launch failed");
    return C;
}
"""

cute_ext = load_inline(
    name="cute_triu_matmul_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_triu_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "-I/workspace/cutegen_test/cutegen/cutlass/include"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
)


class ModelNew(nn.Module):
    """
    Optimized model that performs matrix multiplication (C = A * B) for
    upper triangular matrices using a custom fused CUTE/CUDA kernel that
    skips block computations that cannot contribute to the upper-triangular
    result.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_triu_matmul(A, B)

